"use client";

import { animate, motion, useMotionValue, useReducedMotion, useTransform, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type PointerEvent, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a pull cord. Pass `checked` to control it, or `defaultChecked` to let it hold its own state. */
export type PullCordProps = Omit<ComponentPropsWithoutRef<"button">, "onChange" | "children"> & {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
};

// The handle was under the finger and the hand supplied the pull, so the
// release may give a little, like a real cord. Nothing else here overshoots.
const THUMB_SPRING: Transition = { type: "spring", stiffness: 420, damping: 18, mass: 1 };
// A click or a key press has no pull of its own, so the cord tugs once and settles.
const TUG: Transition = { duration: 0.36, ease: [0.165, 0.84, 0.44, 1], times: [0, 0.4, 1] };
const TUG_DEPTH = 14;
// The cord at rest is 64px long (h-16).
const CORD_LENGTH = 64;
// The handle never travels further than this, however far the finger goes.
const MAX_PULL = 36;
// A release at or past this depth toggles the switch.
const TRIGGER_PULL = 20;
// Movement under this many pixels is a click, not a drag.
const DRAG_SLOP = 4;

/** Maps the finger's distance to the handle's, easing toward `MAX_PULL` so the cord resists more the further it goes. */
const resist = (distance: number) => (distance <= 0 ? 0 : (MAX_PULL * distance) / (distance + MAX_PULL));

/**
 * Toggles one thing on or off with a hanging cord. Drag the handle down and
 * let go past the trigger depth to toggle; let go sooner and nothing changes.
 * A click, Space and Enter toggle it too. It sizes itself: 44px wide and 128px
 * tall, with room inside for the full stretch.
 */
export function PullCord({
  checked,
  defaultChecked = false,
  onCheckedChange,
  className,
  disabled,
  onClick,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
  ...buttonProps
}: PullCordProps) {
  const [ownChecked, setOwnChecked] = useState(defaultChecked);
  const on = checked ?? ownChecked;
  const reduceMotion = useReducedMotion() ?? false;
  // The pull is set straight on a motion value while the finger moves, so a drag never re-renders React.
  const pull = useMotionValue(0);
  const cordScale = useTransform(pull, (depth) => (CORD_LENGTH + depth) / CORD_LENGTH);
  const [armed, setArmed] = useState(false);
  const gesture = useRef<{ pointerId: number; startY: number } | null>(null);
  // True once the pointer moved far enough to be a drag. The click that follows a drag is then ignored.
  const dragged = useRef(false);

  const toggle = () => {
    if (checked === undefined) setOwnChecked(!on);
    onCheckedChange?.(!on);
  };

  const release = () => {
    setArmed(false);
    if (reduceMotion) pull.set(0);
    else animate(pull, 0, THUMB_SPRING);
  };

  const endGesture = (event: PointerEvent<HTMLButtonElement>, commit: boolean) => {
    if (gesture.current?.pointerId !== event.pointerId) return;
    gesture.current = null;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    if (!dragged.current) return;
    if (commit && pull.get() >= TRIGGER_PULL) toggle();
    release();
  };

  return (
    <button
      {...buttonProps}
      type="button"
      role="switch"
      aria-checked={on}
      disabled={disabled}
      data-armed={armed || undefined}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented) return;
        // A drag already decided on release. A keyboard click has `detail` 0 and always counts.
        if (dragged.current && event.detail > 0) {
          dragged.current = false;
          return;
        }
        dragged.current = false;
        toggle();
        // The tug starts from where the handle is, so a second press mid-tug never jumps back to rest.
        if (!reduceMotion) animate(pull, [pull.get(), TUG_DEPTH, 0], TUG);
      }}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        dragged.current = false;
        if (disabled || event.defaultPrevented || event.button !== 0 || gesture.current) return;
        gesture.current = { pointerId: event.pointerId, startY: event.clientY };
        // Capture keeps the drag alive when the finger leaves the button.
        event.currentTarget.setPointerCapture(event.pointerId);
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        const active = gesture.current;
        if (active?.pointerId !== event.pointerId) return;
        const distance = event.clientY - active.startY;
        if (!dragged.current && Math.abs(distance) < DRAG_SLOP) return;
        dragged.current = true;
        const depth = resist(distance);
        // A tug or a spring-back still running must not fight the finger.
        pull.stop();
        pull.set(depth);
        setArmed(depth >= TRIGGER_PULL);
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event);
        endGesture(event, true);
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        endGesture(event, false);
      }}
      className={cn(
        // `touch-none` stops the page from scrolling under a downward drag.
        "group relative inline-flex h-32 w-11 shrink-0 cursor-grab touch-none select-none flex-col items-center outline-none active:cursor-grabbing",
        "rounded-full focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "disabled:cursor-not-allowed disabled:opacity-50",
        className,
      )}
    >
      <motion.span
        aria-hidden="true"
        style={{ scaleY: cordScale }}
        className="block h-16 w-0.5 origin-top rounded-full bg-foreground/50"
      />
      <motion.span
        aria-hidden="true"
        style={{ y: pull }}
        className={cn(
          "grid size-7 place-items-center rounded-full border-2 border-foreground shadow-sm motion-safe:transition-colors motion-safe:duration-200",
          on ? "bg-foreground" : "bg-background",
        )}
      >
        {/* Filled with a bar when on, hollow with a ring when off, so the state never rests on colour alone. */}
        <span
          className={cn(
            "block motion-safe:transition-transform motion-safe:duration-150",
            on ? "h-3 w-0.5 rounded-full bg-background" : "size-2.5 rounded-full border-2 border-foreground",
            "group-data-armed:scale-125",
          )}
        />
      </motion.span>
    </button>
  );
}
